const base = process.env.PLAYWRIGHT_BASE_URL ?? '';

const SEL = {
	frame: 'body',
	region1: 'header.bar a.back',
	region2: 'header.bar .title',
	region3: 'header.bar .hint',
	region4: 'header.bar .ext',
	region5: '.screen > :nth-child(2)',
	region6: '.screen > :nth-child(3) > :nth-child(1) .main',
	region10: '.screen > :nth-child(4)',
	region11: '.screen > :nth-child(5) > :nth-child(1) .main'
};

test('screen: frame matches the handoff', async ({ page }) => {
	await page.goto(`${base}/browse`);
	await expect(page.locator(SEL.frame)).toBeVisible();

	const frameStyle = await page.locator(SEL.frame).evaluate((node) => {
		const cs = getComputedStyle(node);
		return {
			display: cs.display
		};
	});
	expect(frameStyle.display).toBe('block');
});

test('screen: region1 matches the handoff', async ({ page }) => {
	await page.goto(`${base}/browse`);
	await expect(page.locator(SEL.region1)).toBeVisible();

	const region1Style = await page.locator(SEL.region1).evaluate((node) => {
		const cs = getComputedStyle(node);
		return {
			display: cs.display,
			flexDirection: cs.flexDirection,
			justifyContent: cs.justifyContent,
			rowGap: cs.rowGap,
			columnGap: cs.columnGap,
			paddingTop: cs.paddingTop,
			paddingRight: cs.paddingRight,
			paddingBottom: cs.paddingBottom,
			paddingLeft: cs.paddingLeft,
			borderLeftWidth: cs.borderLeftWidth
		};
	});
	expect(region1Style.display).toBe('flex');
	expect(region1Style.flexDirection).toBe('column');
	expect(region1Style.justifyContent).toBe('center');
	expect(region1Style.rowGap).toBe('4px');
	expect(region1Style.columnGap).toBe('4px');
	expect(region1Style.paddingTop).toBe('0px');
	expect(region1Style.paddingRight).toBe('24px');
	expect(region1Style.paddingBottom).toBe('0px');
	expect(region1Style.paddingLeft).toBe('24px');
	expect(region1Style.borderLeftWidth).toBe('0px');
});

